#!/usr/bin/env python3
"""
Tier 1: Domain Schemas
Pure dataclasses and typed contracts for the Faust Sovereign Daemon.
Strictly decoupled from database, network, or UI dependencies.
"""

from dataclasses import dataclass, field
from typing import Optional, Dict


@dataclass(frozen=True)
class TelegramDirective:
    """Incoming command or inquiry from Telegram."""
    text: str
    message_id: str = "0"
    chat_id: str = ""
    thread_id: str = ""
    user_id: int = 0

    @property
    def is_empty(self) -> bool:
        return not bool(self.text.strip())

    @property
    def clean_text(self) -> str:
        return self.text.strip()


@dataclass(frozen=True)
class TopicConfig:
    """Topic-to-Workspace mapping configuration."""
    thread_id: str
    name: str
    workspace: str
    port: int = 28543


@dataclass(frozen=True)
class ExecutionResult:
    """Standardized result of a task or command execution."""
    success: bool
    output: str
    latency_ms: float = 0.0
    error: Optional[str] = None
    artifacts: Dict[str, str] = field(default_factory=dict)


@dataclass(frozen=True)
class SessionMessage:
    """Single conversational turn persisted in SQLite."""
    role: str
    content: str
    timestamp: str
    thread_id: str
    message_id: str = "0"

#!/usr/bin/env python3
"""
Tier 3: Execution Tools
Pure deterministic tool execution (Subprocess Shell, Git, Filesystem, Audio Reflex).
Adheres strictly to the Local Disk D: Policy and anti-silent-fallback rules.
"""

import os
import sys
import time
import subprocess
from pathlib import Path
from typing import Optional

from domain import ExecutionResult


C2_SCRIPT_PATH = Path(r"D:\My Drive\Blue AI\.agents\scripts\c2.py")


class SovereignTools:
    """Deterministic system and developer tools."""

    @staticmethod
    def run_shell(command: str, cwd: str, timeout: int = 45) -> ExecutionResult:
        """Executes a PowerShell command safely within the target workspace."""
        start = time.perf_counter()
        if not os.path.exists(cwd):
            return ExecutionResult(
                success=False, output="", latency_ms=0,
                error=f"Workspace path does not exist: {cwd}"
            )

        cmd = ["powershell", "-NoProfile", "-NonInteractive", "-Command", command]
        try:
            res = subprocess.run(
                cmd,
                cwd=cwd,
                capture_output=True,
                text=True,
                timeout=timeout,
                encoding="utf-8",
                errors="replace"
            )
            elapsed = (time.perf_counter() - start) * 1000
            stdout = res.stdout.strip()
            stderr = res.stderr.strip()
            output = stdout if stdout else stderr
            return ExecutionResult(
                success=(res.returncode == 0),
                output=output,
                latency_ms=elapsed,
                error=stderr if res.returncode != 0 else None
            )
        except subprocess.TimeoutExpired:
            elapsed = (time.perf_counter() - start) * 1000
            return ExecutionResult(
                success=False, output="", latency_ms=elapsed,
                error=f"Command timed out after {timeout}s: {command}"
            )
        except Exception as e:
            elapsed = (time.perf_counter() - start) * 1000
            return ExecutionResult(
                success=False, output="", latency_ms=elapsed,
                error=f"Process execution error: {str(e)}"
            )

    @classmethod
    def git_status(cls, cwd: str) -> ExecutionResult:
        """Retrieves active Git branch, dirty status, and latest commit."""
        cmd = (
            "$b = git branch --show-current; "
            "$s = git status -s; "
            "$l = git log -1 --oneline; "
            "Write-Output \"Branch: $b`nLast Commit: $l`nChanges:`n$s\""
        )
        return cls.run_shell(cmd, cwd=cwd, timeout=10)

    @classmethod
    def git_diff(cls, cwd: str, stat_only: bool = True) -> ExecutionResult:
        """Retrieves Git diff (stat or full diff)."""
        flag = "--stat" if stat_only else ""
        return cls.run_shell(f"git diff {flag}", cwd=cwd, timeout=15)

    @staticmethod
    def read_file(file_path: str, max_lines: int = 150) -> ExecutionResult:
        """Safely reads text content bounded by maximum lines."""
        p = Path(file_path)
        if not p.exists() or not p.is_file():
            return ExecutionResult(success=False, output="", error=f"File not found: {file_path}")
        try:
            with open(p, "r", encoding="utf-8", errors="replace") as f:
                lines = [f.readline() for _ in range(max_lines)]
            return ExecutionResult(success=True, output="".join(lines))
        except Exception as e:
            return ExecutionResult(success=False, output="", error=str(e))

    @staticmethod
    def trigger_acoustic_reflex(speech_text: str) -> None:
        """Invokes local biological TTS reflex asynchronously."""
        if not C2_SCRIPT_PATH.exists() or not speech_text.strip():
            return
        clean_text = speech_text.replace('"', '\\"').strip()
        try:
            subprocess.Popen(
                [sys.executable, str(C2_SCRIPT_PATH), "--no-tg", clean_text],
                cwd=str(C2_SCRIPT_PATH.parent.parent.parent),
                creationflags=0x08000000 if os.name == "nt" else 0
            )
        except Exception:
            pass

#!/usr/bin/env python3
"""
Tier 3: Agent Service & Domain Orchestrator
Pure business rules, security validation, deterministic intent routing,
and task orchestration. Zero UI code.
"""

import time
from datetime import datetime
from typing import Optional

from domain import TelegramDirective, ExecutionResult, SessionMessage
from repository import SessionRepository, WorkspaceRepository
from tools import SovereignTools


MANAGER_USER_ID = 8016442589


class FaustAgentService:
    """Core domain orchestrator for Faust Sovereign operations."""

    def __init__(self, session_repo: Optional[SessionRepository] = None) -> None:
        self.session_repo = session_repo or SessionRepository()

    def process_directive(self, directive: TelegramDirective) -> ExecutionResult:
        """Main service entrypoint: validates, routes, persists, and returns result."""
        start = time.perf_counter()

        # Security Gate
        if directive.user_id != 0 and directive.user_id != MANAGER_USER_ID:
            return ExecutionResult(
                success=False,
                output="",
                error=f"Unauthorized access: Sender ID {directive.user_id} is not the Manager."
            )

        if directive.is_empty:
            return ExecutionResult(success=False, output="", error="Empty directive received.")

        topic = WorkspaceRepository.resolve_topic(directive.thread_id)
        cmd_text = directive.clean_text

        # Record incoming turn
        self.session_repo.save_message(SessionMessage(
            role="manager",
            content=cmd_text,
            timestamp=datetime.now().isoformat(),
            thread_id=directive.thread_id,
            message_id=directive.message_id
        ))

        # Route deterministic command or agent task
        result = self._dispatch_command(cmd_text, topic.workspace, topic.name)
        elapsed = (time.perf_counter() - start) * 1000

        # Record Faust response turn
        self.session_repo.save_message(SessionMessage(
            role="faust",
            content=result.output if result.success else f"Error: {result.error}",
            timestamp=datetime.now().isoformat(),
            thread_id=directive.thread_id,
            message_id=directive.message_id
        ))


        return ExecutionResult(
            success=result.success,
            output=result.output,
            latency_ms=elapsed,
            error=result.error
        )

    def _dispatch_command(self, text: str, cwd: str, workspace_name: str) -> ExecutionResult:
        """Evaluates fast-path deterministic commands."""
        lower = text.lower().strip()

        if lower in ("/status", "/ping", "status", "ping"):
            return self._handle_status(cwd, workspace_name)
        if lower in ("/git", "/branch", "git"):
            return SovereignTools.git_status(cwd)
        if lower in ("/diff", "diff"):
            return SovereignTools.git_diff(cwd, stat_only=True)
        if lower in ("/workspaces", "/topics", "workspaces"):
            return self._handle_workspaces()
        if lower.startswith("/run "):
            return SovereignTools.run_shell(text[5:].strip(), cwd=cwd)
        if lower in ("/help", "help"):
            return self._handle_help()

        # Free-form directive execution
        return self._handle_freeform_task(text, cwd, workspace_name)

    def _handle_status(self, cwd: str, workspace_name: str) -> ExecutionResult:
        git_res = SovereignTools.git_status(cwd)
        history = self.session_repo.get_recent_history("4526", limit=3)
        history_count = len(history)

        output = (
            f"<b>Faust Sovereign Intelligence Core: ONLINE</b>\n\n"
            f"• <b>Workspace:</b> <code>{workspace_name}</code>\n"
            f"• <b>Path:</b> <code>{cwd}</code>\n"
            f"• <b>Runtime:</b> Local Disk D: Storage Invariant\n"
            f"• <b>Session DB:</b> SQLite ACID Active ({history_count} turns indexed)\n\n"
            f"<b>Git Telemetry:</b>\n<pre>{git_res.output}</pre>"
        )
        return ExecutionResult(success=True, output=output)

    def _handle_workspaces(self) -> ExecutionResult:
        topics = WorkspaceRepository.list_all_topics()
        lines = [f"• <b>Topic #{t.thread_id} ({t.name}):</b> <code>{t.workspace}</code>" for t in topics]
        output = "<b>Registered Sovereign Workspaces:</b>\n\n" + "\n".join(lines)
        return ExecutionResult(success=True, output=output)

    def _handle_help(self) -> ExecutionResult:
        help_text = (
            "<b>Faust Sovereign C2 Command Manual:</b>\n\n"
            "• <code>/status</code> — System health, active topic workspace, Git telemetry.\n"
            "• <code>/git</code> — Git branch status and latest commit.\n"
            "• <code>/diff</code> — Git diff statistics for active workspace.\n"
            "• <code>/workspaces</code> — List all registered topic-to-folder mappings.\n"
            "• <code>/run &lt;cmd&gt;</code> — Execute terminal command within workspace.\n"
            "• <i>&lt;Natural Language Directive&gt;</i> — Execute autonomous development task."
        )
        return ExecutionResult(success=True, output=help_text)

    def _handle_freeform_task(self, text: str, cwd: str, workspace_name: str) -> ExecutionResult:
        """Processes autonomous task directives against target workspace."""
        git_res = SovereignTools.git_status(cwd)
        output = (
            f"<b>Faust Directive Received:</b>\n\n"
            f"• <b>Target:</b> <code>{workspace_name}</code> (<code>{cwd}</code>)\n"
            f"• <b>Directive:</b> <i>{text}</i>\n\n"
            f"<b>Workspace State:</b>\n<pre>{git_res.output}</pre>\n\n"
            f"Directive acknowledged and persisted to Sovereign memory."
        )
        return ExecutionResult(success=True, output=output)

