"""
Tier 4: Telegram Egress Transport
Transmits rich contextual briefings directly to the Manager's mobile Telegram thread.
Enforces the 4-tier functional emoji protocol (⚡, 🔄, ✅, ❌) with direct thread replies.
"""

import json
import urllib.request
import urllib.error
from pathlib import Path
from typing import Optional

CONFIG_PATH = Path(r"D:\My Drive\Blue AI\.agents\config\telegram_config.json")
FALLBACK_CONFIG = Path(r"D:\My Drive\SandBox Projetcs\.agents\config\telegram_config.json")


class TelegramEgress:
    """Telegram Bot API transport client."""

    def __init__(self, config_path: Optional[Path] = None) -> None:
        self.config_path = config_path or (CONFIG_PATH if CONFIG_PATH.exists() else FALLBACK_CONFIG)
        self.bot_token = ""
        self.default_chat_id = ""
        self._load_config()

    def _load_config(self) -> None:
        if not self.config_path.exists():
            return
        try:
            with open(self.config_path, "r", encoding="utf-8") as f:
                data = json.load(f)
            self.bot_token = data.get("bot_token", "")
            self.default_chat_id = str(data.get("chat_id", ""))
        except Exception:
            pass

    def send_briefing(
        self,
        text: str,
        thread_id: str = "",
        reply_to_id: str = "",
        chat_id: str = "",
        emoji: str = ""
    ) -> bool:
        """Sends a structured briefing into the specified Telegram topic thread."""
        if not self.bot_token:
            return False

        target_chat = chat_id or self.default_chat_id
        formatted_text = f"{emoji} {text}" if emoji and not text.startswith(emoji) else text
        chunks = self._chunk_text(formatted_text, max_len=3900)

        success = True
        for chunk in chunks:
            ok = self._post_message(chunk, target_chat, thread_id, reply_to_id)
            if not ok:
                success = False
        return success

    def _chunk_text(self, text: str, max_len: int = 3900) -> list[str]:
        """Splits long reports to prevent Telegram 4096-char limit errors."""
        if len(text) <= max_len:
            return [text]
        chunks = []
        while text:
            if len(text) <= max_len:
                chunks.append(text)
                break
            split_idx = text.rfind("\n", 0, max_len)
            if split_idx == -1:
                split_idx = max_len
            chunks.append(text[:split_idx])
            text = text[split_idx:].lstrip()
        return chunks

    def _post_message(self, text: str, chat_id: str, thread_id: str, reply_to_id: str) -> bool:
        url = f"https://api.telegram.org/bot{self.bot_token}/sendMessage"
        payload = {
            "chat_id": chat_id,
            "text": text,
            "parse_mode": "HTML",
            "disable_web_page_preview": True
        }
        if thread_id and str(thread_id).isdigit() and int(thread_id) > 0:
            payload["message_thread_id"] = int(thread_id)
        if reply_to_id and str(reply_to_id).isdigit() and int(reply_to_id) > 0:
            payload["reply_to_message_id"] = int(reply_to_id)

        try:
            req = urllib.request.Request(
                url,
                data=json.dumps(payload).encode("utf-8"),
                headers={"Content-Type": "application/json"}
            )
            with urllib.request.urlopen(req, timeout=10) as resp:
                return resp.status == 200
        except Exception:
            # Fallback retry without HTML formatting if parsing error occurred
            payload.pop("parse_mode", None)
            try:
                req = urllib.request.Request(
                    url,
                    data=json.dumps(payload).encode("utf-8"),
                    headers={"Content-Type": "application/json"}
                )
                with urllib.request.urlopen(req, timeout=10) as resp:
                    return resp.status == 200
            except Exception:
                return False

