#!/usr/bin/env python3
"""
Faust Antigravity IPC Dispatcher
Receives incoming directives from Telegram/n8n and routes them directly
to the active Antigravity IDE conversation session, supporting Topics.
"""

import os
import sys
import time
import json
import sqlite3
import urllib.request
import urllib.parse
import subprocess
from pathlib import Path
from typing import Optional

LANGUAGE_SERVER_EXE = r"d:\Users\Admin\AppData\Local\Programs\Antigravity IDE\resources\app\extensions\antigravity\bin\language_server_windows_x64.exe"
PRIMARY_WORKSPACES_PATH = Path(r"D:\My Heraclitus\Data Codex\Workplaces\workspaces.json")
FALLBACK_WORKSPACES_PATH = Path(r"D:\Program Data\n8n\workspaces.json")
CONVERSATIONS_DIR = Path(r"C:\Users\Admin\.gemini\antigravity-ide\conversations")
LS_CACHE_FILE = Path(r"D:\Program Data\n8n\ls_address.txt")

def get_workspaces_path() -> Path:
    return PRIMARY_WORKSPACES_PATH if PRIMARY_WORKSPACES_PATH.exists() else FALLBACK_WORKSPACES_PATH

def discover_ls_address() -> str:
    """Discovers active Language Server port/address, with fast file caching."""
    if "ANTIGRAVITY_LS_ADDRESS" in os.environ and os.environ["ANTIGRAVITY_LS_ADDRESS"].strip():
        return os.environ["ANTIGRAVITY_LS_ADDRESS"].strip()

    if LS_CACHE_FILE.exists():
        try:
            cached = LS_CACHE_FILE.read_text(encoding="utf-8").strip()
            if cached:
                return cached
        except Exception:
            pass

    cmd = (
        'Get-CimInstance Win32_Process -Filter "Name = \'language_server_windows_x64.exe\'" | '
        'Where-Object { $_.CommandLine -notlike "*--enable_lsp*" } | '
        'Select-Object -ExpandProperty ProcessId'
    )
    res = subprocess.run(["powershell", "-NoProfile", "-Command", cmd], capture_output=True, text=True)
    pids = [int(p.strip()) for p in res.stdout.split() if p.strip().isdigit()]

    for pid in pids:
        port_cmd = (
            f'(Get-NetTCPConnection -OwningProcess {pid} -State Listen | '
            'Where-Object { $_.LocalAddress -eq "127.0.0.1" } | '
            'Select-Object -ExpandProperty LocalPort)'
        )
        p_res = subprocess.run(["powershell", "-NoProfile", "-Command", port_cmd], capture_output=True, text=True)
        ports = [int(pt.strip()) for pt in p_res.stdout.split() if pt.strip().isdigit()]
        ports.sort(reverse=True)
        for port in ports:
            addr = f"127.0.0.1:{port}"
            try:
                LS_CACHE_FILE.parent.mkdir(parents=True, exist_ok=True)
                LS_CACHE_FILE.write_text(addr, encoding="utf-8")
            except Exception:
                pass
            return addr

    return "127.0.0.1:61053"

def find_latest_conv_for_workspace(target_workspace: str) -> Optional[str]:
    """Inspects conversation SQLite databases to match target workspace."""
    if not CONVERSATIONS_DIR.exists() or not target_workspace:
        return None
    target_clean = target_workspace.lower().replace("\\", "/").rstrip("/")
    dbs = sorted([f for f in CONVERSATIONS_DIR.glob("*.db")], key=lambda f: f.stat().st_mtime, reverse=True)
    for db in dbs[:15]:
        try:
            conn = sqlite3.connect(str(db), timeout=1)
            c = conn.cursor()
            c.execute("SELECT data FROM trajectory_metadata_blob WHERE id = 'main'")
            row = c.fetchone()
            conn.close()
            if row and row[0]:
                raw_text = row[0].decode("latin1", errors="ignore")
                if target_clean in urllib.parse.unquote(raw_text).lower():
                    return db.stem
        except Exception:
            continue
    return None

def resolve_conversation_id(thread_id: str = "") -> str:
    path = get_workspaces_path()
    target_ws = ""
    cached_cid = ""
    if path.exists() and thread_id:
        try:
            with open(path, "r", encoding="utf-8") as f:
                reg = json.load(f)
            topic_info = reg.get("topics", {}).get(str(thread_id), {})
            cached_cid = topic_info.get("conversation_id", "")
            target_ws = topic_info.get("workspace", "")
        except Exception:
            pass

    latest_cid = find_latest_conv_for_workspace(target_ws)
    if latest_cid:
        if latest_cid != cached_cid and path.exists() and thread_id:
            try:
                with open(path, "r", encoding="utf-8") as f:
                    reg = json.load(f)
                if str(thread_id) in reg.get("topics", {}):
                    reg["topics"][str(thread_id)]["conversation_id"] = latest_cid
                    with open(path, "w", encoding="utf-8") as f:
                        json.dump(reg, f, indent=2)
            except Exception:
                pass
        return latest_cid

    return cached_cid or "b557d907-759e-4455-9d14-59ccfeb12ce4"

def get_target_port(thread_id: str) -> int:
    """Resolves IPC port from thread ID registry, defaulting to 28543."""
    path = get_workspaces_path()
    if path.exists() and thread_id:
        try:
            with open(path, "r", encoding="utf-8") as f:
                reg = json.load(f)
            topic_info = reg.get("topics", {}).get(str(thread_id))
            if topic_info and "port" in topic_info:
                return int(topic_info["port"])
        except Exception:
            pass
    return 28543

def ping_listener(text: str, msg_id: str, chat_id: str, thread_id: str = "") -> None:
    port = get_target_port(thread_id)
    wake_url = f"http://127.0.0.1:{port}/wake"
    try:
        payload = json.dumps({
            "text": text,
            "message_id": msg_id,
            "chat_id": chat_id,
            "thread_id": thread_id
        }).encode("utf-8")
        req = urllib.request.Request(
            wake_url,
            data=payload,
            headers={"Content-Type": "application/json"}
        )
        with urllib.request.urlopen(req, timeout=1) as resp:
            if resp.status == 200:
                print(f"Wake listener on port {port} notified.")
    except Exception:
        pass

def dispatch(text: str, msg_id: str = "0", chat_id: str = "", thread_id: str = "") -> bool:
    target_conv_id = resolve_conversation_id(thread_id)
    content = f"Manager Directive via Telegram (Chat: {chat_id}, Thread: {thread_id}, ID: {msg_id}): {text}"
    ls_addr = discover_ls_address()
    env = os.environ.copy()
    env["ANTIGRAVITY_LS_ADDRESS"] = ls_addr
    success = False

    for attempt in range(1, 4):
        try:
            proc = subprocess.run(
                [LANGUAGE_SERVER_EXE, "agentapi", "send-message", target_conv_id, content],
                capture_output=True,
                text=True,
                check=True,
                env=env
            )
            print("Dispatch success:", proc.stdout.strip())
            success = True
            break
        except subprocess.CalledProcessError as e:
            err_msg = e.stderr.strip() or e.stdout.strip()
            print(f"Dispatch attempt {attempt} error (code {e.returncode}): {err_msg}", file=sys.stderr)
            LS_CACHE_FILE.unlink(missing_ok=True)
            env["ANTIGRAVITY_LS_ADDRESS"] = discover_ls_address()
            time.sleep(1)
        except Exception as e:
            print(f"Dispatch attempt {attempt} unexpected error: {e}", file=sys.stderr)
            time.sleep(1)
    if not success:
        try:
            print("[*] send-message failed. Spawning dynamic new conversation in Antigravity IDE...")
            proc = subprocess.run(
                [LANGUAGE_SERVER_EXE, "agentapi", "new-conversation", "--title=Telegram Directive", content],
                capture_output=True,
                text=True,
                check=True,
                env=env
            )
            print("New conversation created:", proc.stdout.strip())
            success = True
        except Exception as e:
            print(f"Failed to spawn new conversation: {e}", file=sys.stderr)

    ping_listener(text, msg_id, chat_id, thread_id)
    return success

if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("Usage: python dispatch_to_faust.py <text> [msg_id] [chat_id] [thread_id]")
        sys.exit(1)

    if len(sys.argv) == 5:
        user_text, message_id, target_chat_id, target_thread_id = sys.argv[1:5]
    elif len(sys.argv) > 5:
        target_thread_id = sys.argv[-1]
        target_chat_id = sys.argv[-2]
        message_id = sys.argv[-3]
        user_text = " ".join(sys.argv[1:-3])
    else:
        user_text = sys.argv[1]
        message_id = sys.argv[2] if len(sys.argv) > 2 else "0"
        target_chat_id = sys.argv[3] if len(sys.argv) > 3 else ""
        target_thread_id = sys.argv[4] if len(sys.argv) > 4 else ""

    ok = dispatch(user_text, message_id, target_chat_id, target_thread_id)
    if not ok:
        sys.exit(1)
